function toggleNotifications(){const p=$('#notificationPanel');if(!p)return;const open=p.classList.contains('hidden');p.classList.toggle('hidden',!open);$('#notifBtn')?.setAttribute('aria-expanded',open?'true':'false');if(open)refreshNotifications(false)}
function showLogin(){$('#loginView').classList.remove('hidden');$('#appView').classList.add('hidden')}function showApp(){$('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden')}function logout(show=true){state.token='';sessionStorage.removeItem('ilink_owner_token');if(state.notificationTimer){clearInterval(state.notificationTimer);state.notificationTimer=null}closeNotifications();showLogin();if(show)toast('Sesi ditutup')}
$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='';try{const r=await api('/api/admin/auth/login',{method:'POST',body:{username:$('#loginUsername').value,password:$('#loginPassword').value}});state.token=r.token;sessionStorage.setItem('ilink_owner_token',r.token);$('#loginPassword').value='';await initialize()}catch(err){$('#loginError').textContent=err.message}};$('#logoutBtn').onclick=()=>logout();$('#refreshBtn').onclick=()=>navigate(state.view,true);$('#notifBtn').onclick=e=>{e.stopPropagation();toggleNotifications()};$('#notificationPanel').onclick=e=>e.stopPropagation();$('#notifMarkAll').onclick=async()=>{try{const r=await api('/api/admin/notifications/read',{method:'POST',body:{all:true}});renderNotifications(r);toast('Semua notifikasi ditandai dibaca')}catch(e){toast(e.message,true)}};$('#notificationList').onclick=async e=>{const b=e.target.closest('[data-notif-key]');if(!b)return;try{const r=await api('/api/admin/notifications/read',{method:'POST',body:{keys:[b.dataset.notifKey]}});renderNotifications(r)}catch{}closeNotifications();if(b.dataset.notifView)navigate(b.dataset.notifView)};document.addEventListener('click',closeNotifications);function closeSidebar(){$('#sidebar').classList.remove('open');$('#sidebarBackdrop')?.classList.remove('show')}$('#menuBtn').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#sidebarBackdrop')?.classList.toggle('show',open)};$('#sidebarBackdrop').onclick=closeSidebar;$('#nav').onclick=e=>{const b=e.target.closest('[data-view]');if(b){closeSidebar();navigate(b.dataset.view)}};
function setHeader(view){const[t,s]=titles[view]||[view,''];$('#pageTitle').textContent=t;$('#pageSubtitle').textContent=s;$$('#nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
async function initialize(){state.me=(await api('/api/admin/me')).user;showApp();await navigate('dashboard');await refreshNotifications();if(!state.notificationTimer)state.notificationTimer=setInterval(()=>refreshNotifications(true),60000)}
async function navigate(view){state.view=view;closeNotifications();setHeader(view);$('#content').innerHTML='<div class="empty-product">Memuat data...</div>';try{await({dashboard:loadDashboard,products:loadProducts,fresh:loadFresh,orders:loadOrders,reports:loadReports,coupons:loadCoupons,settings:loadSettings,bot:loadBot,broadcast:loadBroadcast,users:loadUsers}[view]||loadDashboard)();$('#lastUpdated').textContent='Terakhir diperbarui: '+new Date().toLocaleString('id-ID');refreshNotifications(true)}catch(e){$('#content').innerHTML=`<div class="empty-product">${esc(e.message)}</div>`;toast(e.message,true)}}
function applyShell(r){const s=r.settings||{};const o=r.stats||{};state.overview=r;$('#brandName').innerHTML=esc(String(s.store_name||'AUTO ORDER')).replace(/\s+/g,'<br>');$('#brandTagline').textContent=s.store_tagline||'Digital Store';$('#ownerName').textContent=s.owner_display_name||state.me?.display_name||'Owner';$('#ownerUsername').textContent='@'+String(s.owner_username||state.me?.owner_username||'owneradmin').replace(/^@/,'');const metric=String(s.store_balance_metric||o.store_balance_metric||'month_profit');const metricMap={month_profit:['Profit Bulan Ini',o.month_profit],month_revenue:['Omzet Bulan Ini',o.month_revenue],today_profit:['Profit Hari Ini',o.today_profit],today_revenue:['Omzet Hari Ini',o.today_revenue],manual:['Saldo Manual',s.store_balance??o.store_balance]};const selected=metricMap[metric]||metricMap.month_profit;$('#storeBalanceLabel').textContent=selected[0];$('#storeBalance').textContent=money(selected[1]||0);const badgeEl=$('#orderBadge');const pending=Number(o.pending_orders||0);badgeEl.textContent=pending;badgeEl.classList.toggle('hidden',pending<1);const username=state.overview?.bot?.username;$('#telegramBtn').href=username?`https://t.me/${username}`:'#';$('#telegramBtn').textContent='✈ Telegram Mini App';$('#systemSafe').textContent=state.overview?.bot?.running?'Semua sistem berjalan dengan aman':'Dashboard aktif · Bot Telegram offline'}
function stat(icon,color,label,value,small){return`<div class="stat-card"><div class="stat-icon ${color}">${icon}</div><div><small>${esc(label)}</small><strong>${esc(value)}</strong><em>${esc(small)}</em></div></div>`}
function productStockState(p={}){const vars=(p.variants||[]).filter(v=>v.active);if(vars.length){if(vars.some(v=>v.delivery_mode!=='preorder'&&Number(v.stock||0)>0))return'ready';if(vars.some(v=>v.delivery_mode==='preorder'))return'preorder';return'empty'}if(p.delivery_mode==='preorder'&&Number(p.stock||0)<1)return'preorder';return Number(p.sale_stock??p.stock??0)>0?'ready':'empty'}
function stockStateLabel(state,stock=0){return state==='ready'?`READY · ${Number(stock||0)}`:state==='preorder'?'PRE-ORDER':'HABIS'}
function variantChip(v={}){const st=v.delivery_mode==='preorder'?'preorder':Number(v.stock||0)>0?'ready':'empty';const label=st==='ready'?`Ready ${Number(v.stock||0)}`:st==='preorder'?'PO':'Habis';return`<span class="variant-chip stock-${st}" title="${esc(v.name)} · ${label}">${esc(v.name)} · ${label}</span>`}
function productCard(p,i=0){
  const vars=(p.variants||[]).filter(v=>v.active);
  const chips=vars.slice(0,3).map(variantChip).join('')+(vars.length>3?`<span class="variant-chip muted">+${vars.length-3} VARIAN</span>`:'');
  const price=p.price_min===p.price_max?money(p.price_min):`${money(p.price_min)} - ${money(p.price_max)}`;
  const icon=['💎','🤖','🎨','🎬','🛍️'][i%5];
  const thumb=`<span class="thumb-fallback">${icon}</span>${p.image_url?`<img src="${esc(mediaSrc(p.image_url))}" alt="${esc(p.name||'Produk')}" loading="lazy" onerror="this.remove()">`:''}`;
  const stockState=productStockState(p),stockNumber=Number(p.sale_stock??p.stock??0),stockText=stockStateLabel(stockState,stockNumber);
  return `<article class="product-card stock-${stockState}" data-product-card="${p.id}">
    <span class="product-index">${String(i+1).padStart(2,'0')}</span>
    <div class="product-thumb">${thumb}</div>
    <div class="product-body">
      <div class="product-head"><div class="product-title"><h3>${esc(p.name)}</h3><p>${esc(p.subtitle||p.category||'Produk Digital')}</p>${p.tag?`<span class="tag-chip"># ${esc(String(p.tag).replace(/^#/,'').toUpperCase())}</span>`:''}</div><div class="product-head-actions"><span class="stock-state-pill ${stockState}">${stockText}</span><button class="toggle ${p.active?'':'off'}" data-toggle-product="${p.id}" data-active="${p.active?1:0}">${p.active?'ON':'OFF'}</button></div></div>
      <div class="product-info"><div class="info-box stock-box ${stockState}"><small>📦 Stok</small><strong>${stockState==='preorder'?'PO':stockNumber}</strong><em>${stockState==='ready'?'Ready stok':stockState==='preorder'?'Pre-order':'Stok habis'}</em></div><div class="info-box price"><small>🏷 Harga</small><strong>${price}</strong>${bulkTiers(p.bulk_prices).length?`<em>Bulk mulai ${bulkTiers(p.bulk_prices)[0].min_qty} pcs</em>`:''}</div></div>
      <div class="variant-row">${chips||`<span class="variant-chip stock-${stockState}">DEFAULT · ${stockState==='ready'?`Ready ${stockNumber}`:stockState==='preorder'?'PO':'Habis'}</span>`}</div>
      <div class="product-actions"><button class="neo-btn blue small" data-edit-product="${p.id}">✎ EDIT</button><button class="neo-btn green small" data-stock-product="${p.id}">📦 STOK</button><button class="neo-btn yellow small" data-manage-product="${p.id}">⚙ KELOLA</button><button class="neo-btn red small" data-delete-product="${p.id}">🗑 HAPUS</button></div>
    </div>
  </article>`;
}

async function loadDashboard(){
  const [overview,dash]=await Promise.all([api('/api/admin/overview'),api('/api/admin/dashboard')]);
  applyShell(overview);
  const d=dash.data||{},t=d.today||{},daily=d.last7||[],top=d.top_products||[];
  const max=Math.max(1,...daily.map(x=>Number(x.revenue||0)));
  $('#content').innerHTML=`
    <div class="dashboard-kpis">
      ${stat('📈','pink','Omset Hari Ini',money(t.revenue),'Penjualan selesai hari ini')}
      ${stat('💵','green','Profit Hari Ini',money(t.profit),'Profit bersih hari ini')}
      ${stat('🛒','purple','Total Order',t.orders||0,'Order hari ini')}
      ${stat('📦','yellow','Total Stok',d.total_stock||0,'Stok siap kirim')}
    </div>
    <div class="dashboard-grid">
      <section class="report-card chart-card"><div class="card-heading"><div><h3>📊 Grafik 7 Hari Terakhir</h3><p>Omset harian 7 hari terakhir</p></div></div><div class="seven-chart">${daily.map(x=>{const h=Math.max(5,Math.round(Number(x.revenue||0)/max*100));const lbl=new Date(x.day+'T00:00:00').toLocaleDateString('id-ID',{day:'2-digit',month:'short'});return `<div class="day-col"><div class="day-value">${Number(x.revenue||0)?money(x.revenue):'Rp 0'}</div><div class="day-track"><div class="day-bar" style="height:${h}%"></div></div><div class="day-label">${esc(lbl)}</div></div>`}).join('')}</div></section>
      <section class="report-card top-products-card"><div class="card-heading"><div><h3>🏆 Produk Terlaris</h3><p>Berdasarkan jumlah item 7 hari terakhir</p></div></div><div class="top-list">${top.length?top.map((x,i)=>`<div class="top-item"><span class="rank">${i+1}</span><div><b>${esc(x.product_name||'-')}</b><small>${x.qty||0} item · ${x.orders||0} order</small></div><strong>${money(x.revenue)}</strong></div>`).join(''):'<div class="empty compact">Belum ada transaksi 7 hari terakhir.</div>'}</div></section>
    </div>`;
}
function categories(rows){return[...new Set(rows.map(x=>x.category).filter(Boolean))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}function renderProductCards(rows){return rows.length?rows.map(productCard).join(''):'<div class="empty-product"><h3>Belum ada produk</h3><p>Tekan Tambah Produk untuk membuat katalog pertama.</p></div>'}async function loadProducts(){
  const r=await api('/api/admin/products?limit=500');state.cache.products=r.items||[];
  $('#content').innerHTML=`<div class="section-title product-section-title"><div><h2>📦 Katalog Produk</h2><p>Tambah dan edit produk hingga ke varian, deskripsi, dan SNK.</p></div><span><button id="addProduct" class="neo-btn purple">＋ Tambah Produk</button></span></div>
  <div class="toolbar product-toolbar"><div class="searchbox"><input id="productSearch" placeholder="Cari produk..."></div><select id="productCategory"><option value="">Semua Kategori</option>${categories(state.cache.products)}</select><select id="productStatus"><option value="">Semua Status</option><option value="1">Aktif</option><option value="0">Nonaktif</option></select></div>
  <div id="productGrid" class="product-grid">${renderProductCards(state.cache.products)}</div>`;
  $('#addProduct').onclick=()=>openProduct();
  const filter=()=>{const q=$('#productSearch').value.toLowerCase(),cat=$('#productCategory').value,st=$('#productStatus').value;const rows=state.cache.products.filter(p=>(!q||[p.name,p.code,p.category].some(x=>String(x||'').toLowerCase().includes(q)))&&(!cat||p.category===cat)&&(!st||String(p.active)===st));$('#productGrid').innerHTML=renderProductCards(rows);bindProductActions()};
  $('#productSearch').oninput=filter;$('#productCategory').onchange=filter;$('#productStatus').onchange=filter;bindProductActions();
}
function bindProductActions(){$$('[data-edit-product]').forEach(b=>b.onclick=()=>openProduct(findProduct(b.dataset.editProduct)));$$('[data-stock-product]').forEach(b=>b.onclick=()=>openStock(findProduct(b.dataset.stockProduct)));$$('[data-manage-product]').forEach(b=>b.onclick=()=>openManageProduct(findProduct(b.dataset.manageProduct)));$$('[data-delete-product]').forEach(b=>b.onclick=()=>remove(`/api/admin/products/${b.dataset.deleteProduct}`,'Hapus produk beserta varian dan stoknya?',reloadProducts));$$('[data-toggle-product]').forEach(b=>b.onclick=async()=>{try{await api(`/api/admin/products/${b.dataset.toggleProduct}/toggle`,{method:'POST',body:{active:b.dataset.active!=='1'}});toast('Status produk diperbarui');reloadProducts()}catch(e){toast(e.message,true)}})}function findProduct(id){return(state.cache.products||[]).find(x=>String(x.id)===String(id))||{}}
async function reloadProducts(){return navigate(state.view)}
