    const variantPayload={name:b.variant_name,variant_key:'SUP-'+String(x.id).replace(/[^A-Za-z0-9_-]/g,'').slice(0,40),price:Number(b.price||0),cost:Number(b.cost||0),delivery_mode:'auto',active:true,description:b.description||'',terms:b.terms||'',supplier_source:source,supplier_product_id:String(x.id),supplier_price:Number(x.price||0),supplier_public_price:Number(x.publicPrice||0),supplier_stock:x.stock==null?null:Number(x.stock),supplier_synced_at:new Date().toISOString()};
