      const created=await api('/api/admin/products',{method:'POST',body:{code:b.product_code||safeCode,name:b.product_name||x.name,category:b.category||'Produk Digital',price:Number(b.price||0),cost:Number(b.cost||0),active:true,description:x.description||'',terms:'',delivery_mode:'auto'}});parentId=Number(created.item.id);
