function openVariant(p,v={}){
  const edit=!!v.id;
  modal((edit?'Edit':'Tambah')+' Varian · '+p.name,`<div class="form-grid"><label>Nama Varian<input name="name" required value="${esc(v.name||'')}"></label><label>Key / SKU<input name="variant_key" value="${esc(v.variant_key||'')}"></label><label>Harga Jual<input name="price" type="number" min="0" value="${Number(v.price??p.price??0)}"></label><label>Modal iLink<input name="cost" type="number" min="0" value="${Number(v.cost??p.cost??0)}"></label>${bulkEditorHtml('variantBulk',v.bulk_prices||[])}<label>Mode<select name="delivery_mode"><option value="auto" ${v.delivery_mode!=='preorder'?'selected':''}>AUTO</option><option value="preorder" ${v.delivery_mode==='preorder'?'selected':''}>PRE-ORDER</option></select></label><label>Status<select name="active"><option value="true" ${v.active!==0?'selected':''}>Aktif</option><option value="false" ${v.active===0?'selected':''}>Nonaktif</option></select></label><label>Supplier Source<select name="supplier_source" id="variantSupplierSource"><option value="" ${!v.supplier_source?'selected':''}>Stok Lokal</option><option value="prodseller" ${v.supplier_source==='prodseller'?'selected':''}>ProdSeller</option><option value="aiversehub" ${v.supplier_source==='aiversehub'?'selected':''}>AIVerseHub</option></select></label><label>Produk Supplier<select name="supplier_product_id" id="variantSupplierProduct"><option value="${esc(v.supplier_product_id||'')}">${v.supplier_product_id?esc(v.supplier_product_id):'Pilih supplier terlebih dahulu'}</option></select></label><input type="hidden" name="supplier_price" id="variantSupplierPrice" value="${Number(v.supplier_price||0)}"><input type="hidden" name="supplier_public_price" id="variantSupplierPublicPrice" value="${Number(v.supplier_public_price||0)}"><input type="hidden" name="supplier_stock" id="variantSupplierStock" value="${v.supplier_stock==null?'':Number(v.supplier_stock)}"><input type="hidden" name="supplier_synced_at" id="variantSupplierSynced" value="${esc(v.supplier_synced_at||'')}"><div class="full supplier-link-info" id="variantSupplierInfo">${v.supplier_source?`Terhubung: <b>${esc(v.supplier_source)}</b> · ID <code>${esc(v.supplier_product_id||'-')}</code>`:'Varian menggunakan stok lokal.'}</div><label class="full">Deskripsi Varian<textarea name="description" rows="5">${esc(v.description||'')}</textarea></label><label class="full">SNK Varian<textarea name="terms" rows="5">${esc(v.terms||'')}</textarea></label></div>`,async b=>{['price','cost','supplier_price','supplier_public_price'].forEach(k=>b[k]=Number(b[k]||0));b.bulk_prices=bulkTiers(b.bulk_prices);b.supplier_stock=b.supplier_stock===''?null:Number(b.supplier_stock);b.active=b.active==='true';await api(edit?`/api/admin/variants/${v.id}`:`/api/admin/products/${p.id}/variants`,{method:edit?'PATCH':'POST',body:b});toast('Varian disimpan');await reloadProducts()});
  bindBulkEditor('variantBulk',v.bulk_prices||[]);
  const sourceEl=$('#variantSupplierSource'),productEl=$('#variantSupplierProduct'),info=$('#variantSupplierInfo');
  const fill=async(force=false)=>{const source=sourceEl.value;if(!source){productEl.innerHTML='<option value="">Stok Lokal</option>';$('#variantSupplierPrice').value=0;$('#variantSupplierPublicPrice').value=0;$('#variantSupplierStock').value='';$('#variantSupplierSynced').value='';info.textContent='Varian menggunakan stok lokal.';return;}info.textContent='Memuat katalog supplier...';try{const rows=await loadSupplierCatalog(source,force),selected=v.supplier_source===source?v.supplier_product_id:productEl.value;productEl.innerHTML='<option value="">-- Pilih Produk Supplier --</option>'+rows.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(selected)?'selected':''}>${esc(x.name)} · ${esc(x.id)} · ${esc(supplierPrice(x))} · stok ${x.stock==null?'?':x.stock}</option>`).join('');show();}catch(e){productEl.innerHTML=`<option value="${esc(v.supplier_product_id||'')}">${esc(v.supplier_product_id||'Gagal memuat katalog')}</option>`;info.textContent=e.message;}};
  const show=()=>{const source=sourceEl.value,rows=state.cache.supplierCatalogs?.[source]||[],x=rows.find(r=>String(r.id)===String(productEl.value));if(!x){if(source)info.textContent='Pilih produk supplier.';return;}$('#variantSupplierPrice').value=Number(x.price||0);$('#variantSupplierPublicPrice').value=Number(x.publicPrice||0);$('#variantSupplierStock').value=x.stock==null?'':Number(x.stock);$('#variantSupplierSynced').value=new Date().toISOString();info.innerHTML=`<b>${esc(x.name)}</b> · ID <code>${esc(x.id)}</code> · Harga API <b>${esc(supplierPrice(x))}</b> · Stok API <b>${x.stock==null?'?':x.stock}</b>${x.description?`<br><span>${esc(x.description).slice(0,260)}</span>`:''}`;};
  sourceEl.onchange=()=>fill(true);productEl.onchange=show;if(sourceEl.value)fill(false);
}
function openStock(p){
  const localVariants=(p.variants||[]).filter(v=>!v.supplier_source);const targets=[{id:'',name:'Stok Default',stock:Number(p.stock||0)},...localVariants.map(v=>({id:String(v.id),name:v.name,stock:Number(v.stock||0)}))];
  const variantOpts=targets.map(t=>`<option value="${esc(t.id)}">${esc(t.name)} · ${t.stock} ready</option>`).join('');
  const cards=targets.map(t=>`<div class="stock-target-card"><span>📦</span><div><b>${esc(t.name)}</b><small>${t.stock} stok ready</small></div></div>`).join('');
  modal('Tambah Stok · '+p.name,`<div class="stock-add-layout"><div class="stock-target-grid">${cards}</div><div class="form-grid"><label class="full">Target Stok<select name="variant_id" id="addStockVariant">${variantOpts}</select></label><label class="full">Data Stok<textarea name="text" id="addStockText" rows="13" placeholder="Satu akun / kode / data produk per baris"></textarea></label><div class="full stock-input-summary"><span>Item yang akan ditambahkan</span><b id="addStockCount">0</b></div></div><div class="info-note">Stok supplier dikelola melalui sinkronisasi supplier dan tidak ditambahkan manual. Baris kosong otomatis diabaikan.</div></div>`,async b=>{const lines=String(b.text||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!lines.length)throw new Error('Masukkan minimal 1 data stok.');await api(`/api/admin/products/${p.id}/stock`,{method:'POST',body:{variant_id:b.variant_id?Number(b.variant_id):null,mode:'add',items:lines}});toast(`${lines.length} stok ditambahkan`);await reloadProducts()},{submit:'＋ Tambah Stok'});
  const ta=$('#addStockText'),count=$('#addStockCount');const recount=()=>{if(count)count.textContent=String(ta?String(ta.value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).length:0)};if(ta)ta.oninput=recount;recount();
}

function openOrderEdit(o){modal('Edit Pesanan · '+o.order_ref,`<div class="form-grid"><label>Status<select name="status">${['pending_payment','paid','fresh_processing','fresh_attention','completed','waiting_delivery','supplier_pending','failed','canceled','expired'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Modal Aktual<input name="cost_amount" type="number" value="${Number(o.cost_amount||0)}"></label><label class="full">Catatan<textarea name="note">${esc(o.note||'')}</textarea></label></div>${o.status==='completed'?'<p class="warning-note">Mengubah completed menjadi canceled hanya mengubah status order lokal. Produk/akun yang sudah terkirim tidak otomatis dikembalikan ke stok dan pembayaran tidak otomatis direfund.</p>':''}`,async b=>{b.cost_amount=Number(b.cost_amount||0);await api(`/api/admin/orders/${o.id}`,{method:'PATCH',body:b});toast('Pesanan diperbarui');loadOrders()})}function openFulfill(o){modal('Kirim PRE-ORDER · '+o.order_ref,`<p>Produk: <b>${esc(o.product_name)}</b>${o.variant_name?' · '+esc(o.variant_name):''}</p><label class="field">Produk / akun untuk pembeli<textarea name="delivery_text" required rows="10" placeholder="Email | Password | Link | Kode lisensi"></textarea></label>`,async b=>{await api(`/api/admin/orders/${o.id}/fulfill`,{method:'POST',body:b});toast('Produk dikirim ke pembeli');loadOrders()},{submit:'Kirim Produk'})}function openManualOrder(){const products=(state.cache.products||[]).filter(p=>p.active);if(!products.length)return toast('Belum ada produk aktif di katalog.',true);modal('Pesanan Manual',`<div class="form-grid"><label>Telegram ID<input name="telegram_id"></label><label>Nama Pembeli<input name="buyer_name"></label><label>Produk<select name="product_id" id="manualProduct">${products.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.code)}</option>`).join('')}</select></label><label>Varian<select name="variant_id" id="manualVariant"></select></label><label>Qty<input name="quantity" id="manualQty" type="number" min="1" value="1"></label><label>Harga / item<input name="unit_price" id="manualUnitPrice" type="number" min="0"></label><label>Total<input name="total_price" id="manualTotal" type="number" min="0"></label><label>Modal Total<input name="cost_amount" id="manualCost" type="number" min="0"></label><label>Metode Bayar<input name="payment_method" value="manual"></label><label>Status<select name="status"><option value="completed">completed</option><option value="paid">paid</option><option value="waiting_delivery">waiting_delivery</option><option value="pending_payment">pending_payment</option><option value="canceled">canceled</option></select></label><label class="full">Catatan<textarea name="note"></textarea></label></div>`,async b=>{['product_id','variant_id','quantity','unit_price','total_price','cost_amount'].forEach(k=>b[k]=b[k]?Number(b[k]):(k==='variant_id'?null:0));await api('/api/admin/orders/manual',{method:'POST',body:b});toast('Pesanan manual dibuat dari katalog');loadOrders()});const productEl=$('#manualProduct'),variantEl=$('#manualVariant'),qtyEl=$('#manualQty'),unitEl=$('#manualUnitPrice'),totalEl=$('#manualTotal'),costEl=$('#manualCost');const refresh=()=>{const p=products.find(x=>String(x.id)===productEl.value)||products[0],current=variantEl.value;const opts=[`<option value="">Default · ${money(p.price)}</option>`,...(p.variants||[]).filter(v=>v.active).map(v=>`<option value="${v.id}">${esc(v.name)} · ${money(v.price)}</option>`)];variantEl.innerHTML=opts.join('');if(current&&[...(p.variants||[])].some(v=>String(v.id)===current))variantEl.value=current;calc();};const calc=()=>{const p=products.find(x=>String(x.id)===productEl.value)||products[0],v=(p.variants||[]).find(x=>String(x.id)===variantEl.value),qty=Math.max(1,Number(qtyEl.value||1)),price=bulkUnitPrice(Number(v?.price??p.price??0),v?.bulk_prices??p.bulk_prices,qty),cost=Number(v?.cost??p.cost??0);unitEl.value=price;totalEl.value=price*qty;costEl.value=cost*qty;};productEl.onchange=refresh;variantEl.onchange=calc;qtyEl.oninput=calc;refresh();}
function openWallet(u){if(!u)return;modal('Atur Saldo · '+(u.first_name||u.username||u.telegram_id),`<div class="form-grid"><label>Saldo Utama<input name="balance_main" type="number" min="0" value="${Number(u.balance_main||0)}"></label><label>Saldo Referral<input name="balance_referral" type="number" min="0" value="${Number(u.balance_referral||0)}"></label><label class="full">Telegram ID<input value="${esc(u.telegram_id)}" disabled></label></div>`,async b=>{b.balance_main=Number(b.balance_main||0);b.balance_referral=Number(b.balance_referral||0);await api(`/api/admin/users/${encodeURIComponent(u.telegram_id)}/wallet`,{method:'POST',body:b});toast('Saldo diperbarui');navigate(state.view)})}function openSendMessage(id){modal('Kirim Pesan Telegram',`<label class="field">Telegram ID<input value="${esc(id)}" disabled></label><label class="field" style="margin-top:10px">Pesan<textarea name="message" required rows="8"></textarea></label>`,async b=>{await api('/api/admin/bot/send',{method:'POST',body:{chat_id:id,message:b.message}});toast('Pesan dikirim')},{submit:'Kirim'})}
function openCoupon(x={}){const edit=!!x.id;modal(edit?'Edit Kupon':'Tambah Kupon',`<div class="form-grid"><label>Kode<input name="code" required value="${esc(x.code||'')}"></label><label>Nama Promo<input name="name" value="${esc(x.name||'')}"></label><label>Tipe<select name="discount_type"><option value="fixed" ${x.discount_type!=='percent'?'selected':''}>Nominal</option><option value="percent" ${x.discount_type==='percent'?'selected':''}>Persen</option></select></label><label>Diskon<input name="discount_value" type="number" min="0" value="${Number(x.discount_value||0)}"></label><label>Maks Diskon<input name="max_discount" type="number" min="0" value="${Number(x.max_discount||0)}"></label><label>Minimal Belanja<input name="min_purchase" type="number" min="0" value="${Number(x.min_purchase||0)}"></label><label>Limit Pemakaian<input name="usage_limit" type="number" min="0" value="${Number(x.usage_limit||0)}"></label><label>Status<select name="active"><option value="true" ${x.active!==0?'selected':''}>Aktif</option><option value="false" ${x.active===0?'selected':''}>Nonaktif</option></select></label><label>Mulai<input name="starts_at" type="datetime-local" value=""></label><label>Expired<input name="expires_at" type="datetime-local" value=""></label></div>`,async b=>{['discount_value','max_discount','min_purchase','usage_limit'].forEach(k=>b[k]=Number(b[k]||0));b.active=b.active==='true';if(b.starts_at)b.starts_at=new Date(b.starts_at).toISOString();if(b.expires_at)b.expires_at=new Date(b.expires_at).toISOString();await api(edit?`/api/admin/coupons/${x.id}`:'/api/admin/coupons',{method:edit?'PATCH':'POST',body:b});toast('Kupon disimpan');loadCoupons()})}
function openRedeem(){const products=state.cache.products||[];modal('Generate Redeem Code',`<div class="form-grid"><label>Jumlah Kode<input name="count" type="number" min="1" max="200" value="1"></label><label>Tipe<select name="type" id="redeemType"><option value="balance">Saldo</option><option value="product">Produk</option></select></label><label>Nilai / Qty<input name="value" type="number" min="0" value="10000"></label><label>Produk<select name="product_id"><option value="">-</option>${products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Expired<input name="expires_at" type="datetime-local"></label><label>Kode Custom (jumlah 1)<input name="code"></label></div>`,async b=>{b.count=Number(b.count||1);b.value=Number(b.value||0);b.product_id=b.product_id?Number(b.product_id):null;if(b.expires_at)b.expires_at=new Date(b.expires_at).toISOString();const r=await api('/api/admin/redeem',{method:'POST',body:b});toast(`${r.items.length} kode dibuat`);loadCoupons()})}
async function remove(path,msg,reload){if(!confirm(msg))return;try{await api(path,{method:'DELETE'});toast('Berhasil dihapus');await reload()}catch(e){toast(e.message,true)}}
(async()=>{if(!state.token)return showLogin();try{await initialize()}catch{logout(false)}})();
